    44	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    45	{
    46	    const otPanId panId = 0xdead;
    47	
    48	    otInstance *      instance = NULL;
    49	    otMessage *       message  = NULL;
    50	    otError           error    = OT_ERROR_NONE;
    51	    otMessageSettings settings;
    52	
    53	    VerifyOrExit(size > 0);
    54	
    55	    FuzzerPlatformInit();
    56	
    57	    instance = otInstanceInitSingle();
    58	    otLinkSetPanId(instance, panId);
    59	    otIp6SetEnabled(instance, true);
    60	    otThreadSetEnabled(instance, true);
    61	    otThreadBecomeLeader(instance);
    62	
    63	    settings.mLinkSecurityEnabled = (data[0] & 0x1) != 0;
    64	    settings.mPriority            = OT_MESSAGE_PRIORITY_NORMAL;
    65	
    66	    message = otIp6NewMessage(instance, &settings);
    67	    VerifyOrExit(message != NULL, error = OT_ERROR_NO_BUFS);
    68	
    69	    error = otMessageAppend(message, data + 1, static_cast<uint16_t>(size - 1));
    70	    SuccessOrExit(error);
    71	
    72	    error = otIp6Send(instance, message);
    73	
    74	    message = NULL;
    75	
    76	    VerifyOrExit(!FuzzerPlatformResetWasRequested());
    77	
    78	    for (int i = 0; i < MAX_ITERATIONS; i++)
    79	    {
    80	        while (otTaskletsArePending(instance))
    81	        {
    82	            otTaskletsProcess(instance);
    83	        }
    84	
    85	        FuzzerPlatformProcess(instance);
    86	    }
    87	
    88	exit:
    89	
    90	    if (message != NULL)
    91	    {
    92	        otMessageFree(message);
    93	    }
    94	
    95	    if (instance != NULL)
    96	    {
    97	        otInstanceFinalize(instance);
    98	    }
    99	
   100	    return 0;
